import{_ as o,l as r,o as e,c as l,v as t,p as s,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Calvin 确定性","description":"","frontmatter":{"title":"Calvin 确定性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/calvin-deterministic.md","filePath":"cs/calvin-deterministic.md","lastUpdated":1789023840000}'),E={name:"cs/calvin-deterministic.md"};function h(A,a,C,m,_,u){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="calvin-确定性" tabindex="-1">Calvin 确定性 <a class="header-anchor" href="#calvin-确定性" aria-label="Permalink to &quot;Calvin 确定性&quot;">​</a></h1><div class="epigraph"><p>先对事务输入全局排序再执行：同一日志在每个副本上重放同一调度，锁可在定序后无死锁获取，提交无需 2PC 对话。</p><footer>—— 据 Thomson et al., Calvin, SIGMOD 2012；确定性数据库谱系</footer></div><p><a href="/cs/read-only-snapshot">上一课</a>把只读从写路径拆开。本课不钉 xmin。缺口是分布式写：2PC 阻塞、死锁跨节点。Calvin 一类确定性数据库：先把事务（或锁请求集）写入全局有序日志（Paxos），再按序执行。并发控制续封口；恢复复制续从 ARIES 三阶段开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非确定性：各节点本地 2PL 调度不同，副本不能只重放 SQL 文本。确定性：输入序列唯一决定调度与结果。缺口是<strong>读集必须先声明或先侦察</strong>：否则定序时不知道锁哪些键。只读可走本地快照，但要与定序水位一致。</p><p>与 OCC：Calvin 减少 abort，把冲突变成队列里的顺序。热点键仍串行，只是顺序明确。</p><p><span class="marginnote">Thomson, Diamond, Weng, Ren, Shao, Abadi, SIGMOD 2012。后续 Fauna 等。本课机制，不把产品当标准。Spanner 用真时间戳，路线不同，后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户端提交事务批次 → 定序器编号 → 工作机按号获取锁（无等待环：按键排序加锁）→ 执行 → 提交。失败：确定性重放或标记 abort 占住序号。</p><p>与 WAL：全局日志即事务输入日志，重做是再执行而非生理 redo——粒度不同，恢复课对照影子与生理。</p>',10)),(e(),s(c,null,{default:i(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%BA%8B%E5%8A%A1%E8%BE%93%E5%85%A5%22%5D%20--%3E%20SEQ%5B%22%E5%85%A8%E5%B1%80%E5%AE%9A%E5%BA%8F%E6%97%A5%E5%BF%97%22%5D%0A%20%20SEQ%20--%3E%20LOCK%5B%22%E6%8C%89%E5%BA%8F%E6%8C%89%E9%94%AE%E5%8A%A0%E9%94%81%22%5D%0A%20%20LOCK%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%22%5D%0A%20%20EX%20--%3E%20REP%5B%22%E5%89%AF%E6%9C%AC%E5%90%8C%E4%B8%80%E8%B0%83%E5%BA%A6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>依赖分析：无锁冲突的事务可并行执行仍等价于序。侦察事务先跑一遍读集再定序，增加延迟。与 MVCC：可在定序戳上读版本。</p><p>性能：定序器吞吐是上限；可分区定序但跨分区事务又要合成序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 ARIES CLR。也不把确定性当「无日志」。网络分区时定序器可用性是共识问题，后课分布式。</p><p>后课默认：可先定序再执行以避免 2PC 与死锁。ARIES 三阶段与 CLR：单机生理恢复的完整播放。</p><p>确定性调度把隔离做成「日志里的全序」，应用仍要可重放（无非确定性 UDF）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Calvin 全局定序事务输入，副本同调度，免 2PC 对话。</li><li>需要读集或侦察；热点仍串行。</li><li>下一序列 ARIES 三阶段与 CLR：崩溃恢复播放。</li><li>出处：Thomson et al. SIGMOD 2012；2PC 对照。</li></ul>',9))])}const v=o(E,[["render",h]]);export{f as __pageData,v as default};
